from collections import deque


class ConnectGame:
    def __init__(self, board):
        rows = [
            [cell for cell in line.strip().split(" ") if cell]
            for line in board.splitlines()
            if line.strip()
        ]
        self.grid = rows
        self.size = len(rows)

    def _neighbors(self, row, col):
        for d_row, d_col in ((-1, -1), (-1, 0), (0, -1), (0, 1), (1, -1), (1, 0)):
            n_row, n_col = row + d_row, col + d_col
            if 0 <= n_row < self.size and 0 <= n_col < self.size:
                yield n_row, n_col

    def _connected(self, player, start_cells, goal):
        seen = set(start_cells)
        queue = deque(start_cells)
        while queue:
            row, col = queue.popleft()
            if goal(row, col):
                return True
            for n_row, n_col in self._neighbors(row, col):
                if (n_row, n_col) not in seen and self.grid[n_row][n_col] == player:
                    seen.add((n_row, n_col))
                    queue.append((n_row, n_col))
        return False

    def get_winner(self):
        size = self.size
        if size == 0:
            return ""
        if self._connected("X", [(r, 0) for r in range(size) if self.grid[r][0] == "X"],
                            lambda r, c: c == size - 1):
            return "X"
        if self._connected("O", [(0, c) for c in range(size) if self.grid[0][c] == "O"],
                            lambda r, c: r == size - 1):
            return "O"
        return ""

from collections import deque


class ConnectGame:
    def __init__(self, board):
        self.grid = [
            [cell for cell in line.strip().split(" ") if cell]
            for line in board.splitlines()
            if line.strip()
        ]
        self.rows = len(self.grid)
        self.cols = len(self.grid[0]) if self.grid else 0

    def _neighbors(self, row, col):
        for d_row, d_col in ((-1, -1), (-1, 0), (0, -1), (0, 1), (1, -1), (1, 0)):
            n_row, n_col = row + d_row, col + d_col
            if 0 <= n_row < self.rows and 0 <= n_col < self.cols:
                yield n_row, n_col

    def _connected(self, player, start_cells, goal):
        seen = set(start_cells)
        queue = deque(start_cells)
        while queue:
            row, col = queue.popleft()
            if goal(row, col):
                return True
            for n_row, n_col in self._neighbors(row, col):
                if (n_row, n_col) not in seen and self.grid[n_row][n_col] == player:
                    seen.add((n_row, n_col))
                    queue.append((n_row, n_col))
        return False

    def get_winner(self):
        if self.rows == 0:
            return ""
        if self._connected(
            "X",
            [(r, 0) for r in range(self.rows) if self.grid[r][0] == "X"],
            lambda r, c: c == self.cols - 1,
        ):
            return "X"
        if self._connected(
            "O",
            [(0, c) for c in range(self.cols) if self.grid[0][c] == "O"],
            lambda r, c: r == self.rows - 1,
        ):
            return "O"
        return ""
